    private fun symbol(name: String, d: String): ImageVector =
        ImageVector.Builder(
            name = name, defaultWidth = 24.dp, defaultHeight = 24.dp,
            viewportWidth = 960f, viewportHeight = 960f
        ).apply {
            // Material Symbols use a viewBox of 0 -960 960 960
            addGroup(translationY = 960f)
            addPath(PathParser().parsePathString(d).toNodes(), fill = SolidColor(Color.White))
            clearGroup()
        }.build()
